import{_ as t,o as s,c as r,aj as a}from"./chunks/framework.BdtAaXf2.js";const o="/assets/cover.T714O5t4.png",e="/assets/image-20260729114347894.BFGhZ0Rn.png",i="/assets/diagram_experts.BVidTcBh.png",p="/assets/image-20260729155349712.SdTyySMx.png",d="/assets/image-20260729155449011.hCyu82QC.png",g="/assets/image-20260729160119807.Arh-c7tF.png",l="/assets/diagram_skills.BJ0y3s-m.png",m="/assets/image-20260729160143541.DrhB64u2.png",u="/assets/image-20260729160245372.Bcx1ucM1.png",c="/assets/diagram_models.vUeVLw88.png",_="/assets/image-20260729160347790.Cf1Hk1r8.png",h="/assets/image-20260729160414950.DO3iguNm.png",k="/assets/image-20260729160447466.B3rvDFLA.png",W=JSON.parse('{"title":"我为什么愿意为 WorkBuddy 付费？这 3 个能力，才是真正的护城河","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/我为什么愿意为 WorkBuddy 付费/我为什么愿意为 WorkBuddy 付费.md","filePath":"AI人工智能/我为什么愿意为 WorkBuddy 付费/我为什么愿意为 WorkBuddy 付费.md","lastUpdated":1785313630000,"__rawMarkdown":"# 我为什么愿意为 WorkBuddy 付费？这 3 个能力，才是真正的护城河\\n\\n> 万少：个人站点 \\n>\\n> https://blog.zbztb.cn\\n>\\n> 欢迎进行AI+鸿蒙技术交流\\n\\n![封面图](assets/cover.png)\\n\\n用了一段时间 WorkBuddy 之后，我原本只是想试试看，现在已经**愿意续费**了。不是因为它比别人多了几个模型，而是它把 AI 从一个\\"对话工具\\"升级成了一个\\"工作系统\\"。下面这三个能力，是我觉得最值得付费的地方。\\n\\n\\n\\n\\n\\n\\n\\n## 最近使用WorkBuddy + hy3 做的产品官网\\n\\n\\n\\n![](assets/image-20260729114347894.png)\\n\\n---\\n\\n1. https://videosrt.zbztb.cn/   *为视频做字幕， 从未如此轻松*\\n2. https://uiskin.zbztb.cn/   *通用 UI 风格提示词画廊*\\n3. https://provideo.zbztb.cn/  *把一句话， 变成一条电影感视频*\\n4. https://rgzn.zbztb.cn/ *人工智能训练师 测试题*\\n\\n## 专家和专家团\\n\\n![](assets/diagram_experts.png)\\n\\n普通 AI 工具最大的痛点，是每次都要重新交代背景。你得先说 **我是一名 Java 后端，目前在做一个电商项目，代码风格是……你要帮我……** ，一句话没说明白，它就开始胡说八道。\\n\\n你可以把一个专家理解成一个**预设了专业角色、工作流和上下文的智能体**：\\n\\n- **内容创作专家**知道你的品牌语气、排版偏好和发布平台；\\n- **代码专家**了解你的代码库结构、技术栈和命名规范；\\n- **数据分析专家**能直接读取你的数据文件，按业务口径出结论；\\n- **行业研究专家**自带领域知识库，能做调研、综述和报告；\\n- **设计专家**统一视觉规范，输出配图、海报和原型。\\n\\n对我来说，这个价值的衡量标准很简单：以前要花 5 分钟交代背景的活儿，现在直接 @ 专家，**一句话就能开干**。\\n\\n![](assets/image-20260729155349712.png)\\n\\n---\\n\\n![](assets/image-20260729155449011.png)\\n\\n\\n\\n---\\n\\n内置的**专家**甚至还能领优惠券。。\\n\\n![](assets/image-20260729160119807.png)\\n\\n## 技能与连接器\\n\\n![技能与连接器能力货架](assets/diagram_skills.png)\\n\\n很多 AI 产品在对话框里给你一堆\\"建议\\"，然后任务就结束了。真正要落地，还得你自己去打开邮箱、打开文档、打开 GitHub 一步步操作。\\n\\nWorkBuddy 的\\"技能\\"和\\"连接器\\"把最后这一步也包了。\\n\\n![](assets/image-20260729160143541.png)\\n\\n\\n\\n万少这里因为是使用腾讯比较多的产品，腾讯问卷、腾讯文档、ima知识库等等，所以在办公的领域上提效就特别明显了。\\n\\n![](assets/image-20260729160245372.png)\\n\\n## 多模型加自有 Token\\n\\n![多模型与自有 Token](assets/diagram_models.png)\\n\\nworkbuddy内置有国内顶尖大模型：GLM、Kimi、Minimax等，足够满足复杂任务的需求了。\\n\\n另外目前自家的hy3也是在的免费使用阶段中，不用白不用了。\\n\\n![](assets/image-20260729160347790.png)\\n\\n通过每天签到可以领取积分，积分可以兑换token。\\n\\n![](assets/image-20260729160414950.png)\\n\\n---\\n\\n如果自家的不够用，也可以接入自己单独购买的token套餐。\\n\\n![](assets/image-20260729160447466.png)\\n\\n## 写在最后\\n\\n这三个点加在一起，就是我愿意付费的核心理由：\\n\\n- **专家和专家团** 解决\\"怎么把 AI 用对\\"；\\n- **技能和连接器** 解决\\"怎么把 AI 落地到真实工作流\\"；\\n- **多模型加自有 Token** 解决\\"怎么用得起、用得久、用得安心\\"。\\n\\n很多 AI 工具只做了第一层：给你一个更好的对话框。WorkBuddy 做的是第二层甚至第三层：把一个对话框，变成一支能协作、能执行、能长期陪着你的 AI 工作团队。\\n\\n如果你也在找一款能真正\\"干实事\\"的 AI 工具，WorkBuddy 值得认真试一试。\\n\\n*本文为个人真实体验分享。如果你也在用 WorkBuddy，欢迎在评论区聊聊你最常用的专家或技能。*"}'),b={name:"AI人工智能/我为什么愿意为 WorkBuddy 付费/我为什么愿意为 WorkBuddy 付费.md"};function y(z,n,B,q,A,f){return s(),r("div",null,[...n[0]||(n[0]=[a("",43)])])}const T=t(b,[["render",y]]);export{W as __pageData,T as default};
